        val emailEnabled: Boolean? = null,
        // `HH:MM`.
        val emailLocalTime: String? = null,
        // An IANA name.
        val emailTimezone: String? = null,
    )

    @Serializable
    data class UpdateEntryRequest(
        val body: String? = null,
        // The whole sketch, in order. Replaces what was there.
        val fields: List<SketchField>? = null,
        val name: String? = null,
        val summary: String? = null,
    )

    @Serializable
    data class UpdateGoalsRequest(
        // `null` clears the target; leaving it out leaves it alone.
        val dailyWordGoal: Int? = null,
        // The same, for the week.
        val weeklyWordGoal: Int? = null,
    )

    // Each field is sent only when it changes; an empty string (or list) clears
    // it, which is what a writer emptying the field in the UI means.
    @Serializable
    data class UpdateMetadataRequest(
        val contributors: List<ContributorBody>? = null,
        val description: String? = null,
        // An ISBN or any other identifier. Optional; never required.
        val identifier: String? = null,
        val keywords: List<String>? = null,
        // A BCP 47 tag: `en`, `fr-CA`, `he`.
        val language: String? = null,
        // `YYYY`, `YYYY-MM` or `YYYY-MM-DD`.
        val published: String? = null,
        val publisher: String? = null,
        // `ltr` or `rtl`. Empty follows the language.
        val textDirection: String? = null,
    )

    @Serializable
    data class UpdateProfileRequest(
        // A paragraph about the writer, offered as back matter in any book's
        // export. An empty string clears it.
        val aboutAuthor: String? = null,
        // An empty string clears it.
        val bio: String? = null,
        val displayName: String? = null,
    )

    @Serializable
    data class UpdatePromptRequest(
        val body: String? = null,
        // Pin to this future day.
        val day: String? = null,
        // Take it off its day and put it at the end of the queue.
        val unpin: Boolean? = null,
    )

    @Serializable
    data class UpdatePublicationRequest(
        val closesAt: String? = null,
        // `0` removes the cap.
        val maxReviewers: Int? = null,
        val reviewPrompt: String? = null,
        val spoilerSafe: Boolean? = null,
        val visibility: Visibility? = null,
    )

    @Serializable
    data class UpdateQuestionRequest(
        val position: Int? = null,
        val prompt: String? = null,
    )

    @Serializable
    data class UpdateReviewRequest(
        val audience: ReviewAudience? = null,
        // An empty string clears it.
        val closesAt: String? = null,
        val emails: List<String>? = null,
        // An empty string clears it.
        val prompt: String? = null,
        // The people picked, in full: anyone left out is taken off it. Sent
        // with `emails`, or neither.
        val userIds: List<String>? = null,
    )

    @Serializable
    data class UpdateSceneRequest(
        // Move the scene into a different chapter of the same work.
        val chapterId: String? = null,
        // Leave the scene out of the book (`true`) or put it back: an excluded
        // scene is not exported, not in a version, and not in the word count.
        val excluded: Boolean? = null,
        val location: String? = null,
        val pov: String? = null,
        // A built-in status, or the key of one of the book's own.
        val status: String? = null,
        // Free text: fiction rarely runs on the Gregorian calendar.
        val storyDate: String? = null,
        val summary: String? = null,
        // A word target for this scene. Omit to leave it alone; send `null` to
        // clear it. The nesting is what distinguishes those two — see
        // `present_or_absent`.
        val targetWords: Int? = null,
        val title: String? = null,
    )

    @Serializable
    data class UpdateSettingsRequest(
        // A blank paragraph (double Enter) is a scene break, while writing a book
        // and when turning text into a project.
        val doubleEnterSplitsScenes: Boolean? = null,
        val theme: Theme? = null,
    )

    @Serializable
    data class UpdateStatusRequest(
        // `#rrggbb`.
        val color: String? = null,
        val label: String? = null,
    )

    @Serializable
    data class UpdateSummaryEmailRequest(
        val often: SummaryEmail,
        // The device's IANA timezone, such as `Europe/London`. Kept as it was
        // when left out.
        val timezone: String? = null,
    )

    @Serializable
    data class UpdateTaskRequest(
        val body: String? = null,
        val sceneId: String? = null,
        val state: TaskState? = null,
    )

    @Serializable
    data class UpdateVersionRequest(
        val label: String? = null,
        // What this snapshot was for. Blank clears it.
        val notes: String? = null,
    )

    @Serializable
    data class UpdateWorkRequest(
        val copyrightLine: String? = null,
        val dedication: String? = null,
        val epigraph: String? = null,
        val epigraphSource: String? = null,
        // An empty string clears it.
        val genre: String? = null,
        // Front matter. Each is sent only when it changes; an empty string clears
        // one, which is what a writer emptying the field in the UI means.
        val penName: String? = null,
        val shortTitle: String? = null,
        val status: WorkStatus? = null,
        val subtitle: String? = null,
        val synopsis: String? = null,
        // `YYYY-MM-DD` to reach it by. An empty string clears it.
        val targetDate: String? = null,
        // How long the book is meant to be. `0` clears it.
        val targetWords: Int? = null,
        val title: String? = null,
    )

    @Serializable
    data class User(
        // A paragraph about the writer, reusable as back matter in any book.
        val aboutAuthor: String? = null,
        // When they agreed that text they hand the writing assistant may be sent
        // to the model provider. Separate from summaries: a different use.
        val assistantAllowedAt: String? = null,
        val bio: String? = null,
        val createdAt: String,
        // The writer's daily target in words, when they have set one.
        val dailyWordGoal: Int? = null,
        val displayName: String,
        // A blank paragraph (double Enter) is a scene break: in the web book
        // editor it moves on to the next scene, and turning text into a project
        // splits there as well as at a `--` line.
        val doubleEnterSplitsScenes: Boolean,
        val email: String,
        // When the address was proved. Invitations addressed to it reach this
        // account only once it has been.
        val emailVerifiedAt: String? = null,
        val id: String,
        // A site administrator: curates the daily prompts. Set from the command
        // line only; no request body can change it.
        val isAdmin: Boolean,
        // A site moderator: works the queue and sets short restrictions. Granted
        // from the admin dashboard, never from a request body of the account's own.
        val isModerator: Boolean,
        // Contact details for a submission's first page. Kept on the writer rather
        // than the work, since they are the same for every submission.
        val legalName: String? = null,
        val mailingAddress: String? = null,
        val phone: String? = null,
        // When they agreed that text they ask to summarise may be sent to the
        // model provider. Unset, no summary is ever asked for on their behalf.
        val summariesAllowedAt: String? = null,
        val termsAcceptedAt: String? = null,
        // The version of the terms they last agreed to.
        val termsVersion: Int? = null,
        // How the app looks for them, on every device.
        val theme: Theme,
        // When two-factor sign-in was turned on.
        val totpEnabledAt: String? = null,
        val updatedAt: String,
        // The writer's weekly target in words, when they have set one.
        val weeklyWordGoal: Int? = null,
    )

    @Serializable
    data class UserDetail(
        // What the viewer may do here, so the page shows only those buttons.
        val actions: List<String>,
        val activity: Activity,
        val audit: List<AuditRow>,
        // The suggested next step on the escalation ladder.
        val ladder: List<String>,
        val notes: List<NoteView>,
        val reportsAbout: List<ReportAbout>,
        val reportsBy: List<ReportBy>,
        val restrictions: List<RestrictionView>,
        // Administrators only.
        val sessions: List<SessionRow>? = null,
        val summary: AccountSummary,
    )

    @Serializable
    data class UserList(
        val nextCursor: String? = null,
        val users: List<UserRow>,
    )

    @Serializable
    data class UserRow(
        val createdAt: String,
        val displayName: String,
        // Administrators only.
        val email: String? = null,
        val emailVerified: Boolean,
        val id: String,
        val lastSeenAt: String? = null,
        val openReports: Long,
        val role: StaffRole? = null,
        val status: String,
        // When the restriction behind the status ends. Absent when permanent.
        val statusEnds: String? = null,
        val twoFactor: Boolean,
    )

    @Serializable
    data class Version(
        val createdAt: String,
        val createdBy: String,
        val finalizedAt: String? = null,
        val id: String,
        val label: String,
        val notes: String? = null,
        val number: Int,
        val parentVersionId: String? = null,
        val publishedAt: String? = null,
        // `work`, `chapter` or `scene` — how much of the book this froze.
        val scope: PublicationScope,
        val scopeRefId: String? = null,
        val state: VersionState,
        val wordCount: Int,
        val workId: String,
    )

    @Serializable
    data class VersionContent(
        val createdAt: String,
        val createdBy: String,
        val finalizedAt: String? = null,
        val id: String,
        val label: String,
        val notes: String? = null,
        val number: Int,
        val parentVersionId: String? = null,
        val publishedAt: String? = null,
        // `work`, `chapter` or `scene` — how much of the book this froze.
        val scope: PublicationScope,
        val scopeRefId: String? = null,
        val state: VersionState,
        val wordCount: Int,
        val workId: String,
        val chapters: List<ContentChapter>,
        // Which chapter of `toc` this page holds, from zero.
        val page: Int? = null,
        // Every chapter on offer, in order, when this is one page of them — so a
        // reader can move between pages and count progress along the whole book.
        val toc: List<TocChapter>? = null,
    )

    @Serializable
    data class VersionDetail(
        val createdAt: String,
        val createdBy: String,
        val finalizedAt: String? = null,
        val id: String,
        val label: String,
        val notes: String? = null,
        val number: Int,
        val parentVersionId: String? = null,
        val publishedAt: String? = null,
        // `work`, `chapter` or `scene` — how much of the book this froze.
        val scope: PublicationScope,
        val scopeRefId: String? = null,
        val state: VersionState,
        val wordCount: Int,
        val workId: String,
        val entries: List<VersionEntry>,
        // Free-form labels, lowercased so `Submitted` and `submitted` are one tag.
        val tags: List<String>,
    )

    @Serializable
    data class VersionEntry(
        val chapterId: String,
        val chapterPosition: Int,
        // The chapter's role when the snapshot was taken.
        val chapterRole: String,
        val chapterTitle: String,
        val contentHash: String,
        val id: String,
        val sceneId: String,
        val scenePosition: Int,
        val sceneTitle: String,
        val versionId: String,
        val wordCount: Int,
    )

    @Serializable
    enum class VersionState(val raw: String) {
        @SerialName("draft") draft("draft"),
        @SerialName("published") published("published"),
        @SerialName("final") `final`("final"),
    }

    @Serializable
    data class VersionSummary(
        val createdAt: String,
        val createdBy: String,
        val finalizedAt: String? = null,
        val id: String,
        val label: String,
        val notes: String? = null,
        val number: Int,
        val parentVersionId: String? = null,
        val publishedAt: String? = null,
        // `work`, `chapter` or `scene` — how much of the book this froze.
        val scope: PublicationScope,
        val scopeRefId: String? = null,
        val state: VersionState,
        val wordCount: Int,
        val workId: String,
        // Whether this is the work's pinned snapshot.
        val pinned: Boolean,
        // Tags, but not the manifest: a list of fifty snapshots has no use for
        // fifty manifests.
        val tags: List<String>,
    )

    @Serializable
    enum class Visibility(val raw: String) {
        @SerialName("invited") invited("invited"),
        @SerialName("unlisted") unlisted("unlisted"),
        @SerialName("platform") platform("platform"),
        @SerialName("public") `public`("public"),
    }

    @Serializable
    data class VoteRequest(
        // `1` upvote, `-1` downvote, `0` clears the caller's vote.
        val `value`: Int,
    )

    @Serializable
    data class VoteResponse(
        val commentId: String,
        val score: Int,
        val viewerVote: Int,
    )

    @Serializable
    enum class WindowFilter(val raw: String) {
        @SerialName("closing_soon") closing_soon("closing_soon"),
        @SerialName("open_ended") open_ended("open_ended"),
    }

    @Serializable
    data class WindowSummary(
        // Database calls made while serving them.
        val dbWritesPerSecond: Double,
        val lockSamples: Long,
        // Sampled: how long the write lock took to get, every few seconds.
        val lockWaitMs: Percentiles,
        val windowSeconds: Long,
        val writeMs: Percentiles,
        // Requests that changed something.
        val writeRequestsPerSecond: Double,
    )

    @Serializable
    data class WordFilterTerm(
        // `block`, `hold`, `flag` or `mask`.
        val action: String,
        // JSON array of surfaces.
        val appliesTo: String,
        val createdAt: String,
        val createdBy: String,
        val id: String,
        // `word` or `substring`.
        val matchKind: String,
        val normalized: String,
        val note: String,
        val term: String,
        val updatedAt: String,
    )

    @Serializable
    data class WordList(
        val allow: List<String>,
        val surfaces: List<String>,
        val terms: List<WordFilterTerm>,
    )

    @Serializable
    data class Work(
        val copyrightLine: String? = null,
        val createdAt: String,
        val currentVersionId: String? = null,
        val dedication: String? = null,
        val epigraph: String? = null,
        val epigraphSource: String? = null,
        val genre: Genre? = null,
        val id: String,
        val kind: WorkKind,
        val ownerId: String,
        // The name on the byline, when it is not the writer's own.
        val penName: String? = null,
        // The snapshot the writer wants to find without looking — what they last
        // sent out.
        val pinnedVersionId: String? = null,
        // Short form for a running header; a long title wraps and ruins it.
        val shortTitle: String? = null,
        val status: WorkStatus,
        val subtitle: String? = null,
        val synopsis: String? = null,
        // The day they mean to get there by, `YYYY-MM-DD`.
        val targetDate: String? = null,
        // How long the book is meant to be, when the writer has said.
        val targetWords: Int? = null,
        val templateId: String? = null,
        val title: String,
        val updatedAt: String,
        val wordCount: Int,
    )

    // What the outline tells a client about who it is to this work.
    @Serializable
    data class WorkAccess(
        // The chapters they may change, when they were handed only some. Absent
        // means the whole work. Reading is never narrowed.
        val chapterIds: List<String>? = null,
        // Whether they started the work — the one thing an added owner is not.
        val creator: Boolean,
        // Whose book it is.
        val owner: AuthorCard,
        val role: CollaboratorRole,
    )

    @Serializable
    data class WorkActivity(
        val actorId: String,
        val createdAt: String,
        val id: String,
        val kind: ActivityKind,
        // The title as it was at the time.
        val subject: String,
        val subjectId: String? = null,
        // How many acts this line stands for.
        val times: Int,
        val updatedAt: String,
        val workId: String,
    )

    @Serializable
    enum class WorkKind(val raw: String) {
        @SerialName("novel") novel("novel"),
        @SerialName("novella") novella("novella"),
        @SerialName("short_story") short_story("short_story"),
        @SerialName("serial") serial("serial"),
    }

    @Serializable
    data class WorkLink(
        val id: String,
        val title: String,
    )

    @Serializable
    enum class WorkStatus(val raw: String) {
        @SerialName("draft") draft("draft"),
        @SerialName("published") published("published"),
        @SerialName("final") `final`("final"),
        @SerialName("archived") archived("archived"),
    }

    @Serializable
    data class WritingDay(
        val createdAt: String,
        // The writer's local date, `YYYY-MM-DD`.
        val day: String,
        val id: String,
        val netWords: Int,
        val saves: Int,
        val updatedAt: String,
        val userId: String,
    )

    // Where a writer was in a book: the scene, and the selection in it, as the
    // editor's positions within that scene's document.
    @Serializable
    data class WritingPlace(
        val from: Int,
        val sceneId: String,
        val to: Int,
    )

    @Serializable
    data class WritingSummary(
        // The writer's target, if they have set one.
        val dailyWordGoal: Int? = null,
        // Most recent first, one entry per day the writer showed up.
        val history: List<WritingDay>,
        val savesToday: Int,
        // Consecutive days up to and including today on which they wrote.
        val streak: Int,
        val today: String,
        // The Monday of the week `today` falls in. Weeks start on Monday, as the
        // ISO calendar does.
        val weekStart: String,
        val weeklyWordGoal: Int? = null,
        // Net words from `week_start` to `today`.
        val wordsThisWeek: Int,
        // Net words on `today`, which may be negative on a day spent cutting.
        val wordsToday: Int,
    )
}
